void read_bc(Simulation* simulation, EquationParameters* eq_params, eqType& lEq, BoundaryConditionParameters* bc_params, bcType& lBc)
{
  using namespace consts;
  auto bc_type = bc_params->type.value();
  BoundaryConditionType coupled_bc_type = BoundaryConditionType::bType_Neu;
  std::string oned_input_file;

  if (std::set<std::string>{"Dirichlet", "Dir"}.count(bc_type)) {
    lBc.bType = utils::ibset(lBc.bType, enum_int(BoundaryConditionType::bType_Dir));
    coupled_bc_type = BoundaryConditionType::bType_Dir; 

  } else if (std::set<std::string>{"Neumann", "Neu"}.count(bc_type)) {
    lBc.bType = utils::ibset(lBc.bType, enum_int(BoundaryConditionType::bType_Neu)); 
    coupled_bc_type = BoundaryConditionType::bType_Neu;
    if ((lEq.phys == EquationType::phys_fluid) || (lEq.phys == EquationType::phys_FSI)) {
      lBc.bType = utils::ibset(lBc.bType, enum_int(BoundaryConditionType::bType_bfs));
    }

  } else if (std::set<std::string>{"Traction", "Trac"}.count(bc_type)) {
    lBc.bType = utils::ibset(lBc.bType, enum_int(BoundaryConditionType::bType_trac)); 

    if (bc_params->traction_values_file_path.defined()) { 
      int iM = lBc.iM;
      int iFa = lBc.iFa;
      lBc.gm.nTP = 2;
      auto& com_mod = simulation->com_mod;
      int nsd = com_mod.nsd;
      lBc.gm.dof = nsd;

      lBc.gm.t.resize(2); 
      lBc.gm.d.resize(nsd, com_mod.msh[iM].fa[iFa].nNo, 2);

      lBc.gm.t[0] = 0.0;
      lBc.gm.t[1] = 1.E+10;
      lBc.gm.period = lBc.gm.t[1];
      auto file_name = bc_params->traction_values_file_path.value();

      read_trac_bcff(com_mod, lBc.gm, com_mod.msh[iM].fa[iFa], file_name);

      lBc.bType = utils::ibset(lBc.bType, enum_int(BoundaryConditionType::bType_gen));
      lBc.bType = utils::ibset(lBc.bType, enum_int(BoundaryConditionType::bType_flat));

      if (bc_params->traction_multiplier.defined()) { 
        double rtmp = bc_params->traction_multiplier.value(); 
        lBc.gm.d *= rtmp;
      }

      lBc.eDrn.resize(nsd); 
      lBc.h.resize(nsd);
      lBc.weakDir = false;
      return; 
    }

} else if (ctmp == "General") {
  lBc.bType = utils::ibset(lBc.bType, enum_int(BoundaryConditionType::bType_gen)); 
  int iM = lBc.iM;
  int iFa = lBc.iFa;

  // [NOTE] This is not implemented.
  if (bc_params->bct_file_path.defined()) {
    auto file_name = bc_params->bct_file_path.value();
    read_bct(com_mod, lBc.gm, com_mod.msh[iM].fa[iFa], file_name);

  } else {
    if (bc_params->temporal_and_spatial_values_file_path.defined()) {
      auto file_name = bc_params->temporal_and_spatial_values_file_path.value(); 
      read_temp_spat_values(com_mod, com_mod.msh[iM], com_mod.msh[iM].fa[iFa], file_name, lBc); 
    } else {
      throw std::runtime_error("[read_bc] No bct.vtp input file provided for General BC.");
    }

void read_temp_spat_values(const ComMod& com_mod, const mshType& msh, const faceType& lFa, 
    const std::string& file_name, bcType& lBc)
{
  std::ifstream file_stream;
  file_stream.open(file_name);
  if (!file_stream.is_open()) {
    throw std::runtime_error("Failed to open the temporal and spatial values file '" + file_name + "'.");
  }

  int ndof, num_ts, num_nodes;
  file_stream >> ndof >> num_ts >> num_nodes;
  if ((ndof == 0) || (num_ts == 0) || (num_nodes == 0)) {
    throw std::runtime_error("Error reading the first line of the temporal and spatial values file '" + file_name + "'.");
  }

  if (num_nodes != lFa.nNo) {
    throw std::runtime_error("The number of nodes (" + std::to_string(num_nodes) + ") in the temporal and spatial values file '" + 
        file_name + "' are not equal to the number of nodes (" + std::to_string(lFa.nNo) + ") in face '" + lFa.name + "'");
  }

  if ((ndof < 1) || (ndof > com_mod.nsd)) { 
    throw std::runtime_error("The number of degrees of freedom (" + std::to_string(ndof) + ") in the temporal and spatial values file '" +
        file_name + "' don't agree with the number of degrees of freedom (" + std::to_string(com_mod.nsd) + ") of the simulation.");
  }

  lBc.gm.t.resize(num_ts); 
  lBc.gm.d.resize(ndof,num_nodes,num_ts); 
  lBc.gm.dof = ndof;
  lBc.gm.nTP = num_ts;

  Vector<int> ptr(msh.gnNo);
  ptr = -1;

  // Preparing the pointer array
  for (int a = 0; a < lFa.nNo; a++) {
    int Ac = lFa.gN[a];
    Ac = msh.lN[Ac];
    if (Ac == -1) {
      throw std::runtime_error("Incorrect global node number detected for BC for mesh '" + msh.name + 
          "' and face '" + lFa.name + "' for node " + std::to_string(a) + ".");
    }
    ptr[Ac] = a;
  }

  // Read time sequence.
  //
  for (int i = 0; i < num_ts; i++) {
    double rtmp;
    file_stream >> rtmp;
    lBc.gm.t[i] = rtmp;

    if (i == 0) {
      if (!utils::is_zero(rtmp)) { 
        throw std::runtime_error("The first time step (" + std::to_string(rtmp) + 
            ") in the temporal and spatial values file '" + file_name + " is not zero.");
      }

    } else { 
      rtmp = rtmp - lBc.gm.t[i-1];
      if (utils::is_zero(rtmp) || (rtmp < 0.0)) { 
        throw std::runtime_error("A non-increasing time step was found in the temporal and spatial values file '" + 
            file_name + ".");
      }
    }
  }

  lBc.gm.period = lBc.gm.t[num_ts-1];

  // Read in data.
  //
  // Note: This file contains node IDs so be careful
  // to subbtract 1 from them.
  //
  for (int b = 0; b < lFa.nNo; b++) {
    int Ac;
    file_stream >> Ac;
    Ac -= 1;

    if ((Ac >= msh.gnNo) || (Ac < 0)) {
      throw std::runtime_error("The node number " + std::to_string(Ac) + 
            " in the temporal and spatial values file '" + file_name + " is larger than the number of nodes in the mesh.");
    }     

    int a = ptr[Ac];
    if (a == -1) {
      throw std::runtime_error("The node number " + std::to_string(Ac) + 
            " from the temporal and spatial values file '" + file_name + " does not belong to the face '" + lFa.name + "'."); 
    }     

    for (int i = 0; i < num_ts; i++) { 
      double value;
      for (int k = 0; k < ndof; k++) { 
        file_stream >> value;
        lBc.gm.d(k,a,i) = value;
      }
    } 
  } 
}

void read_trac_bcff(ComMod& com_mod, MBType& lMB, faceType& lFa, const std::string& fName)
{
  if (FILE *file = fopen(fName.c_str(), "r")) {
      fclose(file);
  } else {
    throw std::runtime_error("The VTK VTP traction data file '" + fName + "' can't be read.");
  }

  // Read the vtk file.
  //
  auto vtk_data = VtkData::create_reader(fName);
  int num_points = vtk_data->num_points();
  if (num_points == 0) {
    throw std::runtime_error("The VTK VTP traction data file '" + fName + "' does not contain any points.");
  }

  int num_elems = vtk_data->num_elems();
  if (num_elems == 0) {
    throw std::runtime_error("The VTK VTP traction data file '" + fName + "' does not contain any elements.");
  }

  // Set the name of the data to get from the file.
  //
  std::string data_name;
  if (lMB.dof == 1) {
    data_name = "Pressure";
  } else { 
    data_name = "Traction";
  }

  // Check that the vtk file has traction data.
  if (!vtk_data->has_point_data(data_name)) {
    throw std::runtime_error("No PointData DataArray named '" + data_name + "' found in the VTK VTP traction data file '" + fName +
        "' for the '" + lFa.name + "' face.");
  }

  Vector<double> tmpX1(num_points); 
  Array<double> tmpX2(consts::maxNSD, num_points);

  // Set coordinates.
  //
  faceType gFa;
  gFa.nNo = num_points;
  gFa.x.resize(com_mod.nsd, gFa.nNo);
  vtk_data->copy_points(tmpX2);

  for (int i = 0; i < num_points; i++) {
    for (int j = 0; j < com_mod.nsd; j++) {
      gFa.x(j, i) = tmpX2(j, i); 
    }
  }

  if (data_name == "Pressure") {
    vtk_data->copy_point_data(data_name, tmpX1);
  } else { 
    vtk_data->copy_point_data(data_name, tmpX2);
  }

  // Project traction from gFa to lFa. First prepare lFa%x, lFa%IEN
  //
  lFa.x.resize(com_mod.nsd, lFa.nNo);

  for (int a = 0; a < lFa.nNo; a++) {
    int Ac = lFa.gN[a];
    lFa.x.set_col(a, com_mod.x.col(Ac));
  }

  Vector<int> ptr(lFa.nNo);
  ptr = -1;
  gFa.name = "face from traction vtp";
  face_match(com_mod, lFa, gFa, ptr);

  // Copy pressure/traction data to MB data structure
  //
  if (lMB.dof == 1) {
    for (int a = 0; a < lFa.nNo; a++) {
      int Ac = ptr[a];
      lMB.d(0,a,0) = -tmpX1[Ac];
      lMB.d(0,a,1) = -tmpX1[Ac];
    }

  } else { 
    for (int a = 0; a < lFa.nNo; a++) {
      int Ac = ptr[a];
      for (int i = 0; i < lMB.dof; i++) {
        lMB.d(i,a,0) = tmpX2(i,Ac);
        lMB.d(i,a,1) = tmpX2(i,Ac);
      }
    }
  }
}

for (int iBc = 0; iBc < eq.nBc; iBc++) {
  auto& bc = eq.bc[iBc];
  int iFa = bc.iFa;
  int iM = bc.iM;
  #ifdef debug_set_bc_neu
  dmsg << "----- iBc " << iBc+1;
  #endif

  if (utils::btest(bc.bType, iBC_Ris0D))  {continue;}

  // Coupled BCs with DIR type must be handled by set_bc_dir (velocity profile),
  // not here.  Only NEU Coupled BCs get a Neumann pressure traction.
  bool isCoupledDir = utils::btest(bc.bType, iBC_Coupled) &&
                      (bc.coupled_bc.get_bc_type() == BoundaryConditionType::bType_Dir);
  if ((utils::btest(bc.bType, iBC_Neu) || utils::btest(bc.bType, iBC_Coupled)) && !isCoupledDir) {
    #ifdef debug_set_bc_neu
    dmsg << "iM: " << iM+1;
    dmsg << "iFa: " << iFa+1;
    dmsg << "name: " << com_mod.msh[iM].fa[iFa].name;
    #endif
    set_bc_neu_l(com_mod, cm_mod, bc, com_mod.msh[iM].fa[iFa], solutions);

  } else if (utils::btest(bc.bType,iBC_trac)) { 
    set_bc_trac_l(com_mod, cm_mod, bc, com_mod.msh[iM].fa[iFa], solutions);
  } 
}

void set_bc_trac_l(ComMod& com_mod, const CmMod& cm_mod, const bcType& lBc, const faceType& lFa, const SolutionStates& solutions)
{
  // Local alias for old displacement
  const auto& Do = solutions.old.get_displacement();

  using namespace consts;

  #define n_debug_set_bc_trac_l 
  #ifdef debug_set_bc_trac_l 
  DebugMsg dmsg(__func__, com_mod.cm.idcm());
  dmsg.banner();
  #endif

  const int nsd = com_mod.nsd;
  const int dof = com_mod.dof;
  const int tnNo = com_mod.tnNo;
  const int cEq = com_mod.cEq;
  const auto& eq = com_mod.eq[cEq];
  auto& cDmn = com_mod.cDmn;

  int iM = lFa.iM;
  int nNo = lFa.nNo;
  int eNoN = lFa.eNoN;
  #ifdef debug_set_bc_trac_l 
  dmsg << "eNoN: " << eNoN;
  dmsg << "nNo: " << nNo;
  #endif

  // Geting the contribution of traction BC
  //
  Array<double> hg(nsd,tnNo);

  if (utils::btest(lBc.bType,iBC_gen)) {
    Array<double> tmpA(nsd,nNo), hl(nsd,nNo);
    all_fun::igbc(com_mod, lBc.gm, tmpA, hl);
    for (int a = 0; a < nNo; a++) {
      int Ac = lFa.gN(a);
      hg.set_col(Ac, tmpA.col(a));
    }

  } else if (utils::btest(lBc.bType,iBC_std)) {
    for (int a = 0; a < nNo; a++) {
      int Ac = lFa.gN(a);
      hg.set_col(Ac, lBc.h);
    }

  } else if (utils::btest(lBc.bType,iBC_ustd)) {
    if (lBc.gt.get_n_components() != nsd) {
      throw std::runtime_error(
          "[set_bc_trac_l]  Traction dof not initialized properly");
    }
     const Vector<double> h = lBc.gt.value(com_mod.time);
     for (int a = 0; a < nNo; a++) {
       int Ac = lFa.gN(a);
       hg.set_col(Ac, h);
      }

  } else {
    throw std::runtime_error("[set_bc_trac_l] Undefined time dependence for traction BC on face '" +  lFa.name + "'.");
  }

  Vector<double> N(eNoN); 
  Vector<int> ptr(eNoN); 
  Array<double> hl(nsd,eNoN), lR(dof,eNoN);
  Array3<double> lK(dof*dof,eNoN,eNoN);

  // Constructing LHS/RHS contribution and assembiling them
  //
  for (int e = 0; e < lFa.nEl; e++) {
    cDmn = all_fun::domain(com_mod, com_mod.msh[iM], cEq, lFa.gE(e));
    auto cPhys = eq.dmn[cDmn].phys;

    if (lFa.eType == ElementType::NRB) {
      //CALL NRBNNXB(msh(iM), lFa, e)
    }

    for (int a = 0; a < eNoN; a++) {
      int Ac = lFa.IEN(a,e);
      ptr(a) = Ac;
      hl.set_col(a, hg.col(Ac));
    }

    lK = 0.0;
    lR = 0.0;

    for (int g = 0; g < lFa.nG; g++) {
      auto Nx = lFa.Nx.slice(g);
      const Vector<double> nV = nn::gnnb(com_mod, lFa, e, g, Nx, solutions);
      double Jac = utils::norm(nV);
      double w = lFa.w(g)*Jac;
      N = lFa.N.col(g);

      Vector<double> h(nsd);
      for (int a = 0; a < eNoN; a++) {
        h = h + N(a)*hl.col(a);
      }

      for (int a = 0; a < eNoN; a++) {
        for (int i = 0; i < nsd; i++) {
          lR(i,a) = lR(i,a) - w*N(a)*h(i);
        }
      }
    }

    eq.linear_algebra->assemble(com_mod, eNoN, ptr, lK, lR);
  }

BoundaryConditionParameters::BoundaryConditionParameters() {
  // A parameter that must be defined.
  bool required = true;

  // Set name from  Add_BC name="" XML element.
  name = Parameter<std::string>("name", "", required);

  set_parameter("Apply_along_normal_direction", false, !required,
                apply_along_normal_direction);
  set_parameter("Bct_file_path", "", !required, bct_file_path);

  set_parameter("Damping", 1.0, !required, damping);
  set_parameter("Distal_pressure", {}, !required, distal_pressure);

  set_parameter("Effective_direction", {}, !required, effective_direction);
  // set_parameter("Effective_direction", {0,0,0}, !required,
  // effective_direction);
  set_parameter("Follower_pressure_load", false, !required,
                follower_pressure_load);
  set_parameter("Fourier_coefficients_file_path", "", !required,
                fourier_coefficients_file_path);

  set_parameter("Impose_flux", false, !required, impose_flux);
  set_parameter("Impose_on_state_variable_integral", false, !required,
                impose_on_state_variable_integral);
  set_parameter("Initial_displacements_file_path", "", !required,
                initial_displacements_file_path);

  set_parameter("Penalty_parameter", 0.0, !required, penalty_parameter);
  set_parameter("Penalty_parameter_normal", 0.0, !required,
                penalty_parameter_normal);
  set_parameter("Penalty_parameter_tangential", 0.0, !required,
                penalty_parameter_tangential);
  set_parameter("Prestress_file_path", "", !required, prestress_file_path);
  set_parameter("Profile", "Flat", !required, profile);

  set_parameter("Ramp_function", false, !required, ramp_function);

  set_parameter("CST_shell_bc_type", "", !required, cst_shell_bc_type);
  set_parameter("Spatial_profile_file_path", "", !required,
                spatial_profile_file_path);
  set_parameter("Spatial_values_file_path", "", !required,
                spatial_values_file_path);
  set_parameter("Stiffness", 1.0, !required, stiffness);

  set_parameter("Temporal_and_spatial_values_file_path", "", !required,
                temporal_and_spatial_values_file_path);
  set_parameter("Temporal_values_file_path", "", !required,
                temporal_values_file_path);
  set_parameter("Time_dependence", "Steady", !required, time_dependence);
  set_parameter("Traction_values_file_path", "", !required,
                traction_values_file_path);
  set_parameter("Traction_multiplier", 1.0, !required, traction_multiplier);
  set_parameter("Type", "", required, type);

  set_parameter("Undeforming_neu_face", false, !required, undeforming_neu_face);
  set_parameter("Value", 0.0, !required, value);

  set_parameter("Weakly_applied", false, !required, weakly_applied);
  set_parameter("Zero_out_perimeter", false, !required, zero_out_perimeter);

  set_parameter("Resistance", 1.e5, !required, resistance);
}
